import 'package:flutter_super/flutter_super.dart';

void main() => runApp(const SuperApp(child: MyApp()));

class MyApp extends StatelessWidget {
  const MyApp({super.key});
  @override
  Widget build(BuildContext context) => const MaterialApp(home: HomeView());
}

final counter = Super.init(CountNotifier());
class CountNotifier extends RxNotifier<int> {
  @override
  int initial() => 0;
  void increment() => state++;
}
class HomeView extends StatelessWidget {
  const HomeView({super.key});
  @override
  Widget build(BuildContext context) => Scaffold(
    body: Center(
      child: SuperBuilder(builder: (_) => Text('${counter.state}')),
    ),
    floatingActionButton: FloatingActionButton(onPressed: counter.increment),
  );
}
